<script setup lang="ts">
import type { ProductionInputRow, ProductionOutputRow, ProductionMaterialEffect, ProductionMaterialResult } from '~/types/production'
import type { HoldingAmounts } from '~/types/receipt'
import { displayDecimal } from '~/utils/catalog'
defineProps<{ inputs: ProductionInputRow[]; outputs: ProductionOutputRow[]; materials: Array<ProductionMaterialEffect | ProductionMaterialResult>; total: string }>()
const amount = (value: HoldingAmounts | null, unit: string) => value ? `${displayDecimal(value.quantity)}${unit} · ${value.value === null ? '가치 미확인' : `${displayDecimal(value.value)}원`}` : '아직 정산 기준 없음'
</script>
<template>
  <div class="production-result"><p class="preview-result">총 투입 원가 {{ displayDecimal(total) }}원</p>
    <div class="production-result-columns"><section><h3>실제 투입과 원가</h3><ol class="history-list"><li v-for="row in inputs" :key="row.position"><NuxtLink :to="`/materials/${row.material_id}`">{{ row.material_name }}</NuxtLink><p>{{ displayDecimal(row.input_quantity) }}{{ row.input_unit }} · {{ displayDecimal(row.value) }}원</p><p class="field-hint">기준 수량 {{ displayDecimal(row.quantity) }}{{ row.unit }}</p><details><summary>당시 품목 버전</summary><p class="material-id">{{ row.material_version_id }}</p></details></li></ol></section><section><h3>실제 결과와 원가 배분</h3><ol class="history-list"><li v-for="row in outputs" :key="row.position"><NuxtLink :to="`/materials/${row.material_id}`">{{ row.material_name }}</NuxtLink><p>{{ displayDecimal(row.input_quantity) }}{{ row.input_unit }} · {{ displayDecimal(row.value) }}원</p><p>원가 배분 {{ displayDecimal(row.allocation_percent) }}%</p><p class="field-hint">기준 수량 {{ displayDecimal(row.quantity) }}{{ row.unit }}</p><details><summary>당시 품목 버전</summary><p class="material-id">{{ row.material_version_id }}</p></details></li></ol></section></div>
    <section class="production-effects"><h3>품목별 정산 기준 변화</h3><article v-for="effect in materials" :key="effect.material_id" class="production-effect"><h4><NuxtLink :to="`/materials/${effect.material_id}`">{{ [...inputs, ...outputs].find(row => row.material_id === effect.material_id)?.material_name ?? '품목 보기' }}</NuxtLink></h4><dl class="business-price-comparison"><div><dt>이전 정산 기준</dt><dd>{{ amount(effect.before, effect.unit) }}</dd></div><div><dt>생산 후 정산 기준</dt><dd>{{ amount(effect.after, effect.unit) }}</dd></div><div><dt>투입 합계</dt><dd>{{ displayDecimal(effect.input_quantity) }}{{ effect.unit }} · {{ displayDecimal(effect.input_value) }}원</dd></div><div><dt>결과 합계</dt><dd>{{ displayDecimal(effect.output_quantity) }}{{ effect.unit }} · {{ displayDecimal(effect.output_value) }}원</dd></div><div><dt>마지막 확인 수량</dt><dd>{{ effect.observation ? `${displayDecimal(effect.observation.quantity)}${effect.unit}` : '아직 확인한 수량 없음' }}</dd></div></dl><details v-if="effect.basis_before?.id || 'id' in effect"><summary>정산 근거 참조</summary><p v-if="effect.basis_before?.id" class="material-id">이전 근거 {{ effect.basis_before.id }}</p><p v-if="'id' in effect" class="material-id">이 생산의 근거 {{ effect.id }}</p></details></article></section>
    <p class="field-hint">정산 기준은 실제 투입과 결과를 반영한 값입니다. 생산 기록으로 새로 계량한 현재 수량을 만들지 않습니다.</p>
  </div>
</template>
